/* toast stack */
.ts-wrap{position:relative;width:100%;max-width:380px;height:300px}
.ts-stack{position:absolute;left:0;right:0;bottom:0;top:0}
.ti{position:absolute;left:0;right:0;bottom:0;display:flex;align-items:flex-start;gap:12px;padding:12px 12px 12px 14px;background:var(--panel);border:1px solid var(--line);transform-origin:bottom center;transition:transform .5s var(--ease),opacity .35s ease;box-shadow:0 10px 30px -18px rgba(0,0,0,.6)}
.ti .ibx{width:28px;height:28px;flex:none;display:grid;place-items:center;border:1px solid var(--icon-line);background:var(--icon-bg)}
.ti .tt{font-weight:600;font-size:14px}
.ti .tdd{font-size:13px;color:var(--text-dim);margin-top:1px}
.ti .x{margin-left:auto;color:var(--muted);width:22px;height:22px;display:grid;place-items:center;flex:none;transition:color .2s}
.ti .x:hover{color:var(--text)}
.ti .act{margin-top:8px;font-family:var(--mono);font-weight:700;font-size:10px;text-transform:uppercase;color:var(--accent)}

/* ---------- toast stack ---------- */
{
  const wrap = $('#ts-wrap'), stack = $('#ts-stack');
  const msgs = [
    { ic:'check_circle', c:'s-done', t:'Frames exported', d:'12 frames sent to the handoff folder', a:'Open folder' },
    { ic:'nearby_error', c:'s-run', t:'Approval needed', d:'The agent is waiting on the pricing change', a:'Review' },
    { ic:'error', c:'s-fail', t:'Sync failed', d:'The repository rejected the push', a:'Retry' },
    { ic:'stars', c:'s-run', t:'Draft ready', d:'Onboarding copy is ready to read', a:'Read draft' }
  ];
  let k = 0, expanded = false; const list = [];
  function layout(){
    let y = 0;
    list.forEach((t, i) => {
      const h = t.offsetHeight;
      if (expanded){ t.style.transform = `translateY(${-y}px)`; t.style.opacity = '1'; y += h + 8; }
      else { t.style.transform = `translateY(${-i * 12}px) scale(${1 - i * .05})`; t.style.opacity = i > 2 ? '0' : String(1 - i * .12); }
      t.style.zIndex = String(10 - i);
    });
  }
  function remove(t){
    const i = list.indexOf(t); if (i < 0) return; list.splice(i, 1); clearTimeout(t._tm);
    t.style.opacity = '0'; t.style.transform += ' translateX(24px)';
    setTimeout(() => t.remove(), 350); layout();
  }
  function add(silent){
    const m = msgs[k++ % msgs.length];
    const t = document.createElement('div'); t.className = 'ti'; t.setAttribute('role', 'status');
    t.innerHTML = `<span class="ibx">${ic(m.ic, 'sm ' + m.c)}</span><div><div class="tt">${m.t}</div><div class="tdd">${m.d}</div><button class="act">${m.a}</button></div><button class="x" aria-label="Dismiss">${ic('close','sm')}</button>`;
    t.querySelector('.x').addEventListener('click', () => { Sound.play('tick'); remove(t); });
    t.querySelector('.act').addEventListener('click', () => { Sound.play('select'); remove(t); });
    t.style.transform = 'translateY(24px)'; t.style.opacity = '0';
    stack.appendChild(t); list.unshift(t);
    if (list.length > 4) remove(list[list.length - 1]);
    raf2(layout);
    if (!silent) Sound.play('pop'); else ambient('c28', 'pop');
  }
  wrap.addEventListener('mouseenter', () => { expanded = true; layout(); });
  wrap.addEventListener('mouseleave', () => { expanded = false; layout(); });
  $('#ts-add').addEventListener('click', () => add());
  whenSeen($('#c28'), () => { add(true); setTimeout(() => add(true), 700); setTimeout(() => add(true), 1400); });
}
